-- PostgreSQL tourist attractions mock data (100 rows)
-- precautions is stored as a JSONB array of strings.

BEGIN;

CREATE TABLE IF NOT EXISTS tourist_attractions (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    city VARCHAR(50) NOT NULL,
    area VARCHAR(50) NOT NULL,
    name VARCHAR(150) NOT NULL,
    address VARCHAR(255) NOT NULL,
    description TEXT NOT NULL,
    precautions JSONB NOT NULL DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT tourist_attractions_precautions_is_array
        CHECK (jsonb_typeof(precautions) = 'array'),
    CONSTRAINT tourist_attractions_location_unique
        UNIQUE (city, area, name, address)
);

CREATE INDEX IF NOT EXISTS idx_tourist_attractions_city_area
    ON tourist_attractions (city, area);

CREATE INDEX IF NOT EXISTS idx_tourist_attractions_name
    ON tourist_attractions (name);

ON CONFLICT (city, area, name, address) DO UPDATE SET
    description = EXCLUDED.description,
    precautions = EXCLUDED.precautions,
    updated_at = CURRENT_TIMESTAMP;

COMMIT;
