INSERT INTO tourist_attractions
    (city, area, name, address, description, precautions)
VALUES
    ('서울', '종로구', '경복궁', '서울특별시 종로구 사직로 161', '전통 건축과 역사적인 경관을 감상할 수 있는 문화유산입니다. 주요 전각과 정원을 둘러보며 역사를 체험할 수 있습니다.', '["관람 시간과 휴관일을 방문 전에 확인해 주세요.","문화재 보호를 위해 출입 제한 구역에 들어가지 마세요.","시설물에 손을 대거나 음식물을 반입하지 않도록 주의해 주세요."]'::jsonb),
    ('서울', '용산구', '남산서울타워', '서울특별시 용산구 남산공원길 105', '아름다운 자연경관과 다양한 탐방로를 갖춘 야외 명소입니다. 계절에 따라 서로 다른 산행 풍경을 즐길 수 있습니다.', '["방문 전 기상 정보와 탐방로 통제 여부를 확인해 주세요.","미끄럼 방지 기능이 있는 편한 신발과 충분한 물을 준비해 주세요.","일몰 전에 하산할 수 있도록 소요 시간을 미리 계산해 주세요."]'::jsonb),
    ('서울', '송파구', '롯데월드타워 서울스카이', '서울특별시 송파구 올림픽로 300', '지역을 대표하는 볼거리와 고유한 분위기를 즐길 수 있는 관광 명소입니다. 주변 산책과 사진 촬영, 문화 체험을 함께 즐기기 좋습니다.', '["운영 시간과 휴무일, 입장 가능 여부를 방문 전에 확인해 주세요.","주말과 공휴일에는 주차장과 주요 관람 구역이 혼잡할 수 있습니다.","현장 안내 표지와 안전요원의 지시에 따라 이용해 주세요."]'::jsonb),
    ('서울', '종로구', '북촌한옥마을', '서울특별시 종로구 계동길 37', '독특한 골목 풍경과 지역의 생활문화를 경험할 수 있는 관광 명소입니다. 천천히 걸으며 다양한 볼거리를 만날 수 있습니다.', '["주민이 실제 거주하는 구역에서는 소음을 자제해 주세요.","사유지에 무단으로 출입하거나 주거 공간을 촬영하지 마세요.","경사와 계단이 있을 수 있으므로 편한 신발을 권장합니다."]'::jsonb),
    ('서울', '마포구', '홍대거리', '서울특별시 마포구 어울마당로 94', '지역을 대표하는 볼거리와 고유한 분위기를 즐길 수 있는 관광 명소입니다. 주변 산책과 사진 촬영, 문화 체험을 함께 즐기기 좋습니다.', '["주말과 식사 시간에는 보행로와 주변 주차장이 혼잡할 수 있습니다.","개별 점포의 영업시간과 휴무일이 다를 수 있습니다.","귀중품을 잘 보관하고 통행에 방해되지 않도록 주의해 주세요."]'::jsonb),
    ('서울', '영등포구', '여의도한강공원', '서울특별시 영등포구 여의동로 330', '도심 속 자연과 산책로를 즐길 수 있는 휴식 명소입니다. 계절마다 달라지는 풍경과 여러 편의시설을 만날 수 있습니다.', '["운영 시간과 휴무일, 입장 가능 여부를 방문 전에 확인해 주세요.","주말과 공휴일에는 주차장과 주요 관람 구역이 혼잡할 수 있습니다.","현장 안내 표지와 안전요원의 지시에 따라 이용해 주세요."]'::jsonb),
